import functools
import time

def retry(func):
    """
    A decorator that retries a function up to 3 times if an exception is raised.

    Args:
        func (callable): The function to be decorated.

    Returns:
        callable: The wrapped function with retry logic.
    """
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        max_attempts = 3
        last_exception = None

        for attempt in range(1, max_attempts + 1):
            try:
                return func(*args, **kwargs)
            except Exception as e:
                last_exception = e
                print(f"Attempt {attempt} failed for '{func.__name__}': {e}")

                if attempt < max_attempts:
                    print("Retrying...")
                    time.sleep(0.5)  # Small delay between retries
                else:
                    print(f"All {max_attempts} attempts failed.")

        # If all attempts fail, raise the last caught exception
        raise last_exception

    return wrapper

# --- Demonstration Code ---

@retry
def unstable_function(fail_until_attempt: int):
    """
    A dummy function that fails for a specified number of attempts.
    """
    if not hasattr(unstable_function, "_current_attempt"):
